using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
// Targeted migration: only compound box poses on the owned six trailer wrecks.
public static class RefreshWreckCollision
{
 static bool Temporary(Transform t){for(var p=t;p;p=p.parent){var n=p.name.ToLowerInvariant();if(n.Contains("loadinground")||n.Contains("ejectedcase")||n.Contains("spentcase")||n.Contains("powdercase")||n.Contains("projectile")||n=="shell_loaded"||n=="shell_casing"||n.Contains("rammer")||n.Contains("crank")||n.Contains("lensglow")||n.Contains("lensglare")||n.Contains("searchlightbeam")||n.Contains("topattacksubmunitiontemplate"))return true;}return false;}
 public static object Run(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var scene=EditorSceneManager.NewPreviewScene();var rows=new List<object>();int total=0;try{foreach(var guid in AssetDatabase.FindAssets("t:Prefab",new[]{"Assets/Blueprinter/Mods/Gunmageddon"})){var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(AssetDatabase.GUIDToAssetPath(guid));var unit=prefab.GetComponent<GroundVehicle>();if(!unit)continue;var wreck=new SerializedObject(unit).FindProperty("wreckage").objectReferenceValue as GameObject;if(!wreck||!AssetDatabase.GetAssetPath(wreck).Contains("/Wreckage/"))continue;var source=UnityEngine.Object.Instantiate(prefab);SceneManager.MoveGameObjectToScene(source,scene);source.transform.SetPositionAndRotation(Vector3.zero,Quaternion.identity);var pitches=new HashSet<Transform>();foreach(var turret in source.GetComponentsInChildren<Turret>(true)){var p=new SerializedObject(turret).FindProperty("elevationTransform").objectReferenceValue as Transform;if(p)pitches.Add(p);turret.transform.localRotation*=Quaternion.Euler(0,13,0);}foreach(var gun in source.GetComponentsInChildren<Gun>(true))if(gun.transform.name.IndexOf("Pitch",StringComparison.OrdinalIgnoreCase)>=0)pitches.Add(gun.transform);foreach(var pitch in pitches)pitch.localRotation=Quaternion.Euler(12,0,0);Physics.SyncTransforms();var expected=source.GetComponentsInChildren<Collider>(true).Where(c=>!c.isTrigger&&c.enabled&&c.gameObject.activeInHierarchy&&!Temporary(c.transform)&&c.bounds.size.sqrMagnitude>=.001f).ToArray();var root=PrefabUtility.LoadPrefabContents(AssetDatabase.GetAssetPath(wreck));int changed=0;try{var actual=root.GetComponents<BoxCollider>();if(actual.Length!=expected.Length)throw new Exception("Unexpected collider count: "+wreck.name);for(int i=0;i<actual.Length;i++){if(Vector3.Distance(actual[i].center,expected[i].bounds.center)<=.001f&&Vector3.Distance(actual[i].size,expected[i].bounds.size)<=.001f)continue;actual[i].center=expected[i].bounds.center;actual[i].size=expected[i].bounds.size;changed++;}if(changed>0)PrefabUtility.SaveAsPrefabAsset(root,AssetDatabase.GetAssetPath(wreck));}finally{PrefabUtility.UnloadPrefabContents(root);}total+=changed;rows.Add(new{unit=unit.definition.unitName,colliders=expected.Length,changed});UnityEngine.Object.DestroyImmediate(source);}string json=Newtonsoft.Json.JsonConvert.SerializeObject(new{passed=true,changed=total,units=rows});File.WriteAllText(System.IO.Path.Combine((System.Environment.GetEnvironmentVariable("GUNMAGGEDON_ROOT") ?? throw new System.InvalidOperationException("Set GUNMAGGEDON_ROOT before running editor tools or fixtures.")), "GunmaggedonRuntime/build/wreckage/collision-fit.json"),json);return json;}finally{EditorSceneManager.ClosePreviewScene(scene);}}
}
